class Solution:
    def sampleStats(self, count):
        n = sum(count)
        mn = mx = mode = -1
        best = total = 0
        for i, c in enumerate(count):
            if c > 0:
                if mn == -1:
                    mn = i
                mx = i
                total += c * i
                if c > best:
                    best = c
                    mode = i

        def kth(k):
            acc = 0
            for i, c in enumerate(count):
                acc += c
                if acc >= k:
                    return i

        if n % 2:
            med = float(kth((n + 1) // 2))
        else:
            med = (kth(n // 2) + kth(n // 2 + 1)) / 2.0
        return [float(mn), float(mx), total / n, med, float(mode)]

