class Solution {
public:
    vector<double> sampleStats(vector<int>& count) {
        long long n = 0, total = 0;
        int mn = -1, mx = -1, mode = -1;
        long long best = 0;
        for (int i = 0; i < 256; ++i) {
            long long c = count[i];
            n += c;
            total += c * (long long)i;
            if (c > 0) {
                if (mn == -1) mn = i;
                mx = i;
            }
            if (c > best) { best = c; mode = i; }
        }
        auto kth = [&](long long k) {
            long long acc = 0;
            for (int i = 0; i < 256; ++i) {
                acc += count[i];
                if (acc >= k) return i;
            }
            return 255;
        };
        double med;
        if (n % 2) med = kth((n + 1) / 2);
        else med = (kth(n / 2) + kth(n / 2 + 1)) / 2.0;
        return {(double)mn, (double)mx, (double)total / n, med, (double)mode};
    }
};

