from itertools import accumulate
import bisect

class Solution:
    def sampleStats(self, count):
        pref = list(accumulate(count))
        n = pref[-1]
        mn = next(i for i, c in enumerate(count) if c > 0)
        mx = max(i for i, c in enumerate(count) if c > 0)
        mode = max(range(256), key=lambda i: count[i])
        total = sum(i * c for i, c in enumerate(count))

        def kth(k):
            return bisect.bisect_left(pref, k)

        if n % 2:
            med = float(kth((n + 1) // 2))
        else:
            med = (kth(n // 2) + kth(n // 2 + 1)) / 2.0
        return [float(mn), float(mx), total / n, med, float(mode)]

