class Solution {
    public double[] sampleStats(int[] count) {
        long[] pref = new long[256];
        long run = 0;
        for (int i = 0; i < 256; i++) { run += count[i]; pref[i] = run; }
        long n = pref[255], total = 0;
        int mn = -1, mx = -1, mode = 0;
        for (int i = 0; i < 256; i++) {
            total += (long) count[i] * i;
            if (count[i] > 0) {
                if (mn == -1) mn = i;
                mx = i;
            }
            if (count[i] > count[mode]) mode = i;
        }
        java.util.function.LongUnaryOperator kth = k -> {
            int lo = 0, hi = 255;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (pref[mid] >= k) hi = mid; else lo = mid + 1;
            }
            return lo;
        };
        double med;
        if (n % 2 == 1) med = kth.applyAsDouble((n + 1) / 2);
        else med = (kth.applyAsDouble(n / 2) + kth.applyAsDouble(n / 2 + 1)) / 2.0;
        return new double[]{mn, mx, (double) total / n, med, mode};
    }
}

